/**
 * @fileoverview Test the usage of a removed property
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-removed-property-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

/**
 * These tests would result in issues being reported by the no-removed-property-usage
 * rule due to how doxi output would misflag several 'methods' as 'properties'.
 * A quick fix has been done by editing the generated doxi of older versions (< 6)
 * and so we need these tests in case someone regenerates the doxi for older versions
 * since it will reintroduce this issue.
 */
const getPreviousDoxInvalidTests = function () {
    const code = `
        Ext.getBody();
        Ext.getDoc();
        Ext.JSON.encode(data);
        Ext.Array.contains();
    `;

    return [
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '4.0',
                    toVersion: '7.9'
                }
            },
            code: code
        },
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '4.1',
                    toVersion: '7.9'
                }
            },
            code: code
        },
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '4.2',
                    toVersion: '7.9'
                }
            },
            code: code
        },
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '5.0',
                    toVersion: '7.9'
                }
            },
            code: code
        },
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '5.1',
                    toVersion: '7.9'
                }
            },
            code: code
        },
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '6.0',
                    toVersion: '7.9'
                }
            },
            code: code
        },
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '6.2',
                    toVersion: '7.9'
                }
            },
            code: code
        },
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '6.5',
                    toVersion: '7.9'
                }
            },
            code: code
        },
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '6.6',
                    toVersion: '7.9'
                }
            },
            code: code
        },
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '7.0',
                    toVersion: '7.9'
                }
            },
            code: code
        }
    ];
};

const ruleTester = new RuleTester();
ruleTester.run('no-removed-property-usage', rule, {

    valid: [].concat(getPreviousDoxInvalidTests()),

    invalid: [
        {
            settings: {
                extjs: {
                    fromVersion: '5.1.4',
                    toVersion: '7.9'
                }
            },
            code: `
                Ext.define('MyCustomChart', {
                    extend: 'Ext.chart.PolarChart',
                    initComponent: function () {
                        this.version = 2; // version property removed in 6.0
                    }
                });
                Ext.define('MyCustomChart', {
                    extend: 'Ext.chart.CartesianChart',
                    initComponent: function () {
                        var me = this;
                        me.version = 2; // version property removed in 6.0
                    }
                });
                Ext.define('MyCustomChart', {
                    override: 'Ext.chart.AbstractChart',
                    initComponent: function () {
                        var me = this;
                        me.version = 2; // version property removed in 6.0
                    }
                });
                Ext.define('MyCustomChart', {
                    extend: 'Ext.chart.SpaceFillingChart',
                    version: 2 // version property removed in 6.0
                });
            `,
            errors: [
                { message: /Usage of removed property 'version' found for 'Ext.chart.PolarChart'/ },
                { message: /Usage of removed property 'version' found for 'Ext.chart.CartesianChart'/ },
                { message: /Usage of removed property 'version' found for 'Ext.chart.AbstractChart'/ },
                { message: /Usage of removed property 'version' found for 'Ext.chart.SpaceFillingChart'/ }
            ]
        }
    ]
});
